//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Computes the delay before a retry, where `retry_number` starts at one.
    pub fn delay_for_retry(&self, retry_number: u32) -> u64 {
        if retry_number == 0 || self.max_delay_ms == 0 {
            return 0;
        }

        let exponent = retry_number - 1;
        let multiplier = 1u64.checked_shl(exponent).unwrap_or(u64::MAX);
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms)
    }
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_attempts: 1,
            base_delay_ms: 0,
            max_delay_ms: 0,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_growth_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: 123,
        };
        assert_eq!(config.delay_for_retry(1), 123);
        assert_eq!(config.delay_for_retry(u32::MAX), 123);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => return Err(error),
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
                attempt += 1;
            }
        }
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn transient(message: &str) -> Result<(), RetryError> {
    Err(RetryError::Transient(message.to_owned()))
}

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 25,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            transient("temporary")
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".to_owned()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".to_owned())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_first_call() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 1,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        transient("still down")
    });

    assert_eq!(result, Err(RetryError::Transient("still down".to_owned())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

#[test]
fn zero_attempt_budget_still_makes_one_call() {
    let config = RetryConfig {
        max_attempts: 0,
        ..RetryConfig::default()
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        transient("temporary")
    });

    assert!(result.is_err());
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn huge_retry_numbers_do_not_overflow() {
    let config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: u64::MAX,
        max_delay_ms: 123,
    };
    assert_eq!(config.delay_for_retry(u32::MAX), 123);
}

#[allow(dead_code)]
fn _uses_transient_helper() {
    let _ = transient("test");
}
